function IdolLive3D_FreeNodesMgr:__init()

    local roleRootTF = IdolLive3D_Utils.FindRootTransformInIdol3DScene("_Role_")
    local buildsRootTF = IdolLive3D_Utils.FindRootTransformInIdol3DScene("_Builds_")
    assert( isNotNull(roleRootTF) and isNotNull(buildsRootTF) )

    self.nodes = {} 
    ---
    local AddFunc = function( parentTF_ )
        local comps = parentTF_:GetComponentsInChildren(typeof(IDPro),true) -- 包含自己, 包含 inactive 的
        for i=0, comps.Length-1 do 
            local idPro = comps[i]
            -- 收集 keyValueList:
            local pairs = {}
            for j=0, idPro.keyValueList.Count-1 do
                local e = idPro.keyValueList[j]
                pairs[string.lower(e.key)] = string.lower(e.value)
            end
            ---
            if isNotNull(pairs.key) and isNotNull(pairs.type) then 
                ---
                if isNull(self.nodes[pairs.key]) then 
                    self.nodes[pairs.key] = {
                        key = pairs.key,
                        transform = idPro.transform,
                        type = pairs.type
                    }
                else 
                    printError("发现重复的 多功能节点, 这个节点将被放弃登记; key:"..tostring(pairs.key)..", type:"..tostring(pairs.type))
                end 
            end 
        end
    end
    AddFunc(roleRootTF)
    AddFunc(buildsRootTF)

    -- debug:
    -- for k,v in pairs(self.nodes) do 
    --     printError("k:" .. tostring(k) .. ", type:" .. tostring(v.type))
    -- end 
    ---
    self.isInit = true
end



