---@param nodeKey_  string 
---@param type_     string
---@return table or nil
function IdolLive3D_FreeNodesMgr:FindNode( nodeKey_, type_ )
    nodeKey_ = string.lower(nodeKey_)
    type_ = string.lower(type_)
    ---
    local e = self.nodes[nodeKey_]
    if e.type == type_ then 
        return e
    end 
    return nil
end


--- 可以把所有 key 中包含 nodeKeyPart_ 的 nodes 找出来
---@param nodeKey_  string  @ key 的子字符串
---@param type_     string
---@return table
function IdolLive3D_FreeNodesMgr:FindNodes( nodeKeyPart_, type_ )
    nodeKeyPart_ = string.lower(nodeKeyPart_)
    type_ = string.lower(type_)
    ---
    local rets = {}
    for key,node in pairs(self.nodes) do 
        if string.find(key, nodeKeyPart_,1,true) ~= nil and node.type == type_ then
            table.insert( rets, node )
        end
    end 
    return rets
end




return IdolLive3D_FreeNodesMgr
